package com.ecommerce.controller;
import com.ecommerce.dao.UserDAO; import com.ecommerce.model.User; import com.ecommerce.util.View; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException;
@WebServlet({"/login","/register","/logout"}) public class AuthServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{String p=req.getServletPath(); if("/logout".equals(p)){req.getSession().invalidate();resp.sendRedirect(req.getContextPath()+"/");return;} View.forward(req,resp,"/login".equals(p)?"login.jsp":"register.jsp");}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{req.setCharacterEncoding("UTF-8");String p=req.getServletPath();UserDAO dao=new UserDAO(); if("/login".equals(p)){User u=dao.login(req.getParameter("email"),req.getParameter("password")); if(u==null){req.setAttribute("error","E-posta veya şifre hatalı");View.forward(req,resp,"login.jsp");return;} req.getSession().setAttribute("user",u);resp.sendRedirect(req.getContextPath()+("ADMIN".equals(u.getRole())?"/admin/dashboard":"/"));} else {String email=req.getParameter("email"); if(dao.emailExists(email)){req.setAttribute("error","Bu e-posta zaten kayıtlı");View.forward(req,resp,"register.jsp");return;} User u=new User();u.setFullName(req.getParameter("fullName"));u.setEmail(email);u.setPassword(req.getParameter("password"));u.setPhone(req.getParameter("phone"));u.setAddress(req.getParameter("address"));u.setRole("CUSTOMER");dao.create(u);req.setAttribute("success","Kayıt başarılı. Giriş yapabilirsiniz.");View.forward(req,resp,"login.jsp");}}catch(Exception e){throw new ServletException(e);}}
}
